SourceCode.Declaration:
/// <summary>
/// Extension class for NumberSeq to handle fixed batch number
/// </summary>
[ExtensionOf(classStr(NumberSeq))]
internal final class AVA_NumberSeq_Extension
{
}

Method.Source:
/// <summary>
/// Returns number - checks for fixed batch number if applicable
/// </summary>
/// <returns>Number from sequence or fixed batch</returns>
public Num num()
{
    Num number;
    InventNumGroup inventNumGroup;
    NumberSeq numberSeq = this;

    // Check if this is for batch number and if fixed batch is configured
    if (numberSeq.parmNumberSequenceCode())
    {
        NumberSeqCode numberSeqCode = numberSeq.parmNumberSequenceCode();

        // Find if this number sequence is used for batch tracking
        select firstonly AVA_FixedBatch, AVA_FixedBatchNumber from inventNumGroup
            where inventNumGroup.Batch == numberSeqCode
                && inventNumGroup.AVA_FixedBatch == NoYes::Yes;

        if (inventNumGroup.AVA_FixedBatchNumber)
        {
            number = inventNumGroup.AVA_FixedBatchNumber;
            return number;
        }
    }

    // Use standard logic
    number = next num();

    return number;
}
